BEGIN;
DO $guard$ BEGIN IF current_database() <> 'Quotation' THEN RAISE EXCEPTION 'database identity mismatch'; END IF; END $guard$;
ALTER TABLE "public"."Quotation" ADD COLUMN "AcceptanceOrigin" character varying(16);
ALTER TABLE "public"."Quotation" ADD COLUMN "AcceptedUtc" text;
ALTER TABLE "public"."Quotation" ADD COLUMN "SourceJourneyID" uuid;
ALTER TABLE "public"."Quotation" ADD COLUMN "SourceRequestID" integer;
CREATE SCHEMA IF NOT EXISTS "legacy_compatibility";
CREATE TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ("ID" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL, "QuotationID" integer NOT NULL, "EventKey" character varying(128) NOT NULL, "EventName" character varying(40) NOT NULL, "ClientId" character varying(128) NOT NULL, "SessionId" character varying(128) NOT NULL, "UserId" character varying(128), "Currency" character varying(3) NOT NULL, "Value" numeric(18,2) NOT NULL, "OccurredUtc" timestamp without time zone NOT NULL, "AttemptCount" integer DEFAULT ((0)) NOT NULL, "NextAttemptUtc" timestamp without time zone NOT NULL, "LeaseToken" uuid, "LeaseUntilUtc" timestamp without time zone, "SentUtc" timestamp without time zone, "FailedUtc" timestamp without time zone, "LastError" character varying(1024), "SourceRequestID" integer, "SourceJourneyID" uuid, "OccurredUtcSubMicrosecondTicks" smallint DEFAULT 0 NOT NULL, "NextAttemptUtcSubMicrosecondTicks" smallint DEFAULT 0 NOT NULL, "LeaseUntilUtcSubMicrosecondTicks" smallint, "SentUtcSubMicrosecondTicks" smallint, "FailedUtcSubMicrosecondTicks" smallint);
CREATE TABLE "public"."QuotationAcceptedOutcome" ("ID" bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL, "EventKey" character varying(128) NOT NULL, "QuotationID" integer NOT NULL, "SourceRequestID" integer, "SourceJourneyID" uuid, "AcceptedUtc" timestamp without time zone NOT NULL, "AcceptanceOrigin" character varying(16) NOT NULL, "AcceptedUtcSubMicrosecondTicks" smallint DEFAULT 0 NOT NULL);
CREATE TABLE "public"."sysdiagrams" ("name" character varying(128) NOT NULL, "principal_id" integer NOT NULL, "diagram_id" integer GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL, "version" integer, "definition" bytea);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "PK_GoogleAnalyticsOutbox" PRIMARY KEY ("ID");
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "CK_GoogleAnalyticsOutbox_OccurredUtcSubMicrosecondTicks" CHECK ("OccurredUtcSubMicrosecondTicks" >= 0 AND "OccurredUtcSubMicrosecondTicks" <= 9);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "CK_GoogleAnalyticsOutbox_NextAttemptUtcSubMicrosecondTicks" CHECK ("NextAttemptUtcSubMicrosecondTicks" >= 0 AND "NextAttemptUtcSubMicrosecondTicks" <= 9);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "CK_GoogleAnalyticsOutbox_LeaseUntilUtcSubMicrosecondTicks" CHECK ("LeaseUntilUtcSubMicrosecondTicks" >= 0 AND "LeaseUntilUtcSubMicrosecondTicks" <= 9);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "CK_GoogleAnalyticsOutbox_SentUtcSubMicrosecondTicks" CHECK ("SentUtcSubMicrosecondTicks" >= 0 AND "SentUtcSubMicrosecondTicks" <= 9);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "CK_GoogleAnalyticsOutbox_FailedUtcSubMicrosecondTicks" CHECK ("FailedUtcSubMicrosecondTicks" >= 0 AND "FailedUtcSubMicrosecondTicks" <= 9);
CREATE INDEX "IX_GoogleAnalyticsOutbox_Due" ON "legacy_compatibility"."GoogleAnalyticsOutbox" ("SentUtc" ASC, "FailedUtc" ASC, "NextAttemptUtc" ASC, "LeaseUntilUtc" ASC);
CREATE INDEX "IX_GoogleAnalyticsOutbox_QuotationID" ON "legacy_compatibility"."GoogleAnalyticsOutbox" ("QuotationID" ASC);
CREATE INDEX "IX_GoogleAnalyticsOutbox_SourceJourneyID" ON "legacy_compatibility"."GoogleAnalyticsOutbox" ("SourceJourneyID" ASC) WHERE ("SourceJourneyID" IS NOT NULL);
CREATE INDEX "IX_GoogleAnalyticsOutbox_SourceRequestID" ON "legacy_compatibility"."GoogleAnalyticsOutbox" ("SourceRequestID" ASC) WHERE ("SourceRequestID" IS NOT NULL);
CREATE UNIQUE INDEX "UX_GoogleAnalyticsOutbox_EventKey" ON "legacy_compatibility"."GoogleAnalyticsOutbox" ("EventKey" ASC);
ALTER TABLE "public"."QuotationAcceptedOutcome" ADD CONSTRAINT "PK_QuotationAcceptedOutcome" PRIMARY KEY ("ID");
CREATE INDEX "IX_QuotationAcceptedOutcome_AcceptedUtc" ON "public"."QuotationAcceptedOutcome" ("AcceptedUtc" ASC);
CREATE UNIQUE INDEX "IX_QuotationAcceptedOutcome_EventKey" ON "public"."QuotationAcceptedOutcome" ("EventKey" ASC);
CREATE INDEX "IX_QuotationAcceptedOutcome_QuotationID" ON "public"."QuotationAcceptedOutcome" ("QuotationID" ASC);
CREATE INDEX "IX_QuotationAcceptedOutcome_SourceJourneyID" ON "public"."QuotationAcceptedOutcome" ("SourceJourneyID" ASC);
CREATE INDEX "IX_QuotationAcceptedOutcome_SourceRequestID" ON "public"."QuotationAcceptedOutcome" ("SourceRequestID" ASC);
ALTER TABLE "public"."sysdiagrams" ADD CONSTRAINT "PK__sysdiagr__C2B05B61A5D700FB" PRIMARY KEY ("diagram_id");
ALTER TABLE "public"."sysdiagrams" ADD CONSTRAINT "UK_principal_name" UNIQUE ("principal_id", "name");
CREATE INDEX "IX_Quotation_SourceJourneyID" ON "public"."Quotation" ("SourceJourneyID" ASC) WHERE ("SourceJourneyID" IS NOT NULL);
CREATE INDEX "IX_Quotation_SourceRequestID" ON "public"."Quotation" ("SourceRequestID" ASC) WHERE ("SourceRequestID" IS NOT NULL);
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" ADD CONSTRAINT "FK_GoogleAnalyticsOutbox_Quotation" FOREIGN KEY ("QuotationID") REFERENCES "public"."Quotation" ("ID") ON DELETE NO ACTION ON UPDATE NO ACTION NOT DEFERRABLE NOT VALID;
ALTER TABLE "legacy_compatibility"."GoogleAnalyticsOutbox" VALIDATE CONSTRAINT "FK_GoogleAnalyticsOutbox_Quotation";
COMMIT;
